import java.util.*;
record P(String n) {}
class Main {
  public static void main(String[] args) {
    Set<P> s = new HashSet<>();
    s.add(new P("a"));
    s.add(new P("a"));
    System.out.println(s.size() + " " + new P("a").equals(new P("a")));
  }
}

