import java.util.*;
class P {
  int x;
  P(int x) { this.x = x; }
  public boolean equals(Object o) { return o instanceof P p && p.x == x; }
}
class Main {
  public static void main(String[] args) {
    Set<P> s = new HashSet<>();
    s.add(new P(1));
    s.add(new P(1));
    System.out.println(s.size());
  }
}

